        if not obs:
            return 0
        best = 999
        for ax, ay in obs:
            d = abs(nx - ax) + abs(ny - ay)
            if d < best:
                best = d
        # Larger when close to obstacles; discourage proximity for stability
        return 10.0 / (1.0 + best)

