            tx, ty = max(corners, key=lambda c: cheb(c[0], c[1], ox, oy))
        else:
            # As evader: go to the corner farthest from the opponent.
            tx, ty = max(corners, key=lambda c: cheb(c[0], c[1], ox, oy))
        return cheb(x, y, tx, ty)

    best = None
    best_score = None
    for dx, dy in moves:
        nx, ny = sx + dx, sy + dy
        if not ok(nx, ny):
            continue
        d = cheb(nx, ny, ox, oy)
        op_block = obstacle_pressure(nx, ny)
        tc = target_corners_score(nx, ny)
        if self_is_pursuer:
